from bulk import B
B("Reef fish","🐠",[
("blue-tang","Blue tang","Paracanthurus hepatus",2,40,["Indo-Pacific"],"~30 cm","~30 years","Zooplankton, algae","Least Concern","A royal-blue surgeonfish with a scalpel-like spine at its tail.","Clear coral reefs with branching corals for shelter.","Juveniles eat plankton; adults graze algae.","Group spawning at dusk; pelagic eggs.","Larvae drift in plankton for weeks before settling.","Hides in coral when threatened and may 'play dead'."),
("yellow-tang","Yellow tang","Zebrasoma flavescens",2,46,["Pacific, especially Hawaii"],"~20 cm","Up to 40 years","Algae","Least Concern","A bright yellow grazer that keeps Hawaiian reefs clear of seaweed.","Shallow reefs and lagoons.","Grazes turf algae with a protruding snout.","Spawns in groups or pairs at the full moon.","Pelagic larvae ~50 days.","Turns paler at night; loose schools by day."),
("moorish-idol","Moorish idol","Zanclus cornutus",3,180,["Indo-Pacific"],"~23 cm","Unknown","Sponges, algae","Least Concern","A striking banded fish with a long trailing dorsal filament.","Reef flats, lagoons and outer reefs.","Picks sponges and invertebrates from crevices with its long snout.","Pelagic spawner with a long larval stage.","Long pelagic larval stage spreads it widely.","Often in pairs or small groups."),
("emperor-angelfish","Emperor angelfish","Pomacanthus imperator",1,100,["Indo-Pacific, Red Sea"],"~40 cm","Up to 20+ years","Sponges, tunicates","Least Concern","Changes completely from a juvenile with white rings to a yellow-and-blue striped adult.","Coral-rich reefs and caves.","One of the few fish that eat sponges.","Protogynous hermaphrodite; a male guards a harem.","Resident.","Makes knocking sounds when disturbed."),
("french-angelfish","French angelfish","Pomacanthus paru",3,100,["Western Atlantic, Caribbean"],"Up to 41 cm","Unknown","Sponges, algae","Least Concern","Lives in lifelong monogamous pairs that defend a territory together.","Shallow reefs.","Sponge specialist; juveniles act as cleaners.","Monogamous pairs spawn at dusk.","Resident.","Pairs are territorial and bold toward divers."),
("butterflyfish-threadfin","Threadfin butterflyfish","Chaetodon auriga",1,60,["Indo-Pacific, Red Sea"],"~23 cm","Unknown","Coral polyps, worms, algae","Least Concern","A typical butterflyfish with an eye-spot near its tail that confuses predators.","Reef flats and lagoons.","Picks polyps and small invertebrates with tweezer-like jaws.","Pairs spawn at dusk.","Pelagic larvae.","Often in pairs; false eye-spot deters attacks."),
("regal-angelfish","Regal angelfish","Pygoplites diacanthus",1,80,["Indo-Pacific"],"~25 cm","Unknown","Sponges, tunicates","Least Concern","Orange, blue and white bands; famously difficult to keep in aquaria.","Coral-rich reefs near caves.","Sponge and tunicate specialist.","Pair spawning.","Resident.","Shy; stays near cover."),
("royal-gramma","Royal gramma","Gramma loreto",1,60,["Caribbean"],"~8 cm","~5 years","Zooplankton, parasites","Least Concern","A half-purple, half-yellow basslet that swims upside down under ledges.","Reef caves and overhangs.","Picks plankton from passing water.","Males build nests of algae and guard eggs.","Resident.","Orients belly to the nearest surface, so swims inverted under ledges."),
("hawkfish-longnose","Longnose hawkfish","Oxycirrhites typus",10,100,["Indo-Pacific"],"~13 cm","Unknown","Small crustaceans","Least Concern","Perches on gorgonian sea fans like a hawk watching for prey.","Steep reef walls with sea fans and black corals.","Ambush from a perch.","Pair spawning at dusk.","Resident.","Territorial; males keep small harems."),
("triggerfish-titan","Titan triggerfish","Balistoides viridescens",1,50,["Indo-Pacific"],"Up to 75 cm","Unknown","Urchins, crabs, molluscs, coral","Least Concern","The largest triggerfish, which fiercely defends cone-shaped nesting zones and bites divers.","Lagoons and seaward reefs.","Flips rocks and blows water to expose prey; crushes urchins.","Nests in sand craters; female guards eggs.","Resident.","Aggressive near nests; locks its dorsal spine ('trigger') in crevices."),
("picasso-triggerfish","Picasso triggerfish","Rhinecanthus aculeatus",0,4,["Indo-Pacific"],"~30 cm","Unknown","Algae, invertebrates, detritus","Least Concern","Its Hawaiian name, humuhumunukunukuāpuaʻa, is one of the longest fish names.","Shallow reef flats and lagoons.","Omnivore grazing and picking.","Benthic nests guarded by females.","Resident.","Grunts when alarmed; wedges into holes at night."),
("porcupinefish","Long-spine porcupinefish","Diodon holocanthus",2,200,["Tropical worldwide"],"~50 cm","Unknown","Molluscs, urchins, crabs","Least Concern","Inflates into a spiny ball when threatened.","Reefs, seagrass, sandy areas.","Fused beak-like teeth crush hard-shelled prey.","Pelagic eggs.","Juveniles drift offshore.","Nocturnal; slow swimmer relying on spines and toxins."),
("pufferfish-whitespotted","White-spotted pufferfish","Torquigener albomaculosus",10,30,["Southern Japan"],"~12 cm","Unknown","Small invertebrates","Not Evaluated","The male builds intricate 2-m geometric 'crop circle' nests in sand to attract females.","Sandy seafloor near reefs.","Feeds on small benthic invertebrates.","Males sculpt circular sand nests for a week; females lay eggs in the centre.","Resident.","Elaborate nest-building courtship discovered only in 1995 and described in 2014."),
("neon-goby","Neon goby","Elacatinus oceanops",1,40,["Western Atlantic, Caribbean"],"~5 cm","~1–2 years","Parasites from client fish","Least Concern","Runs 'cleaning stations' where large fish, even predators, wait to be groomed.","Coral heads and sponges.","Eats ectoparasites from client fish.","Pairs lay eggs in coral crevices.","Resident.","Clients pose with open mouths; mutual trust."),
("mudskipper","Atlantic mudskipper","Periophthalmus barbarus",0,1,["West Africa"],"~25 cm","~5 years","Insects, crabs, worms","Least Concern","A fish that spends more time out of water than in, breathing through its skin.","Mangrove mudflats and estuaries.","Hunts on land, skipping across mud.","Males dig burrows and perform leaping displays; eggs are kept in an air-filled chamber.","Resident.","Territorial; fights with raised fins."),
("garden-eel","Spotted garden eel","Heteroconger hassi",7,45,["Indo-Pacific"],"~40 cm","Unknown","Zooplankton","Least Concern","Colonies of hundreds rise from sand like a garden of stalks.","Sandy slopes swept by currents.","Picks plankton from the current while anchored in its burrow.","Neighbours stretch out to spawn without leaving burrows.","Resident.","Disappears into the sand when approached."),
("frogfish-giant","Giant frogfish","Antennarius commerson",0,70,["Indo-Pacific"],"Up to 38 cm","Unknown","Fish, crustaceans","Least Concern","A master of disguise that 'walks' on its fins and fishes with a lure.","Reefs and sponges.","Wiggles a lure; engulfs prey in ~6 ms by expanding its mouth 12-fold.","Releases eggs in a floating raft.","Resident.","Can change colour over weeks to match sponges."),
("leafy-seadragon","Leafy seadragon","Phycodurus eques",4,50,["Southern Australia"],"~35 cm","~7 years","Mysid shrimp","Least Concern","Leaf-like appendages make it look like drifting seaweed.","Kelp and seagrass beds.","Sucks tiny shrimp through its tube snout.","Males carry eggs on the underside of the tail.","Site-faithful.","Slow drifter relying on camouflage."),
("pipefish-banded","Banded pipefish","Dunckerocampus dactyliophorus",5,56,["Indo-Pacific"],"~19 cm","Unknown","Small crustaceans, parasites","Least Concern","A seahorse relative that also cleans parasites off other fish.","Reef caves and crevices.","Snaps up tiny prey with its tube snout.","Males brood eggs.","Resident.","Often in pairs."),
("grouper-goliath","Atlantic goliath grouper","Epinephelus itajara",0,100,["Atlantic"],"Up to 2.5 m, 360 kg","~37 years","Lobsters, fish, turtles","Vulnerable","A giant grouper that booms to warn intruders; recovering after fishing bans.","Reefs, wrecks and mangroves (juveniles).","Engulfs prey with a vacuum-like gulp.","Spawning aggregations at wrecks in late summer.","Juveniles move from mangroves to reefs.","Territorial; produces loud booming sounds."),
("nassau-grouper","Nassau grouper","Epinephelus striatus",1,100,["Caribbean, western Atlantic"],"Up to 1.2 m","~29 years","Fish, crustaceans","Critically Endangered","Gathers in thousands at a few full-moon spawning sites, which made it easy to overfish.","Coral reefs.","Ambush predator.","Massive spawning aggregations around the winter full moons.","Migrates tens of km to aggregation sites.","Changes colour patterns during courtship."),
("napoleon-wrasse","Humphead wrasse","Cheilinus undulatus",1,100,["Indo-Pacific, Red Sea"],"Up to 2 m","~30 years","Molluscs, crown-of-thorns starfish, urchins","Endangered","A giant wrasse with a bulging forehead, one of the few predators of crown-of-thorns starfish.","Outer reef slopes and channels.","Crushes hard-shelled prey with thick lips and pharyngeal teeth.","Protogynous hermaphrodite; females become males.","Resident with spawning movements.","Long-lived and slow-maturing; targeted by the live-fish trade."),
("bluehead-wrasse","Bluehead wrasse","Thalassoma bifasciatum",0,40,["Caribbean"],"~25 cm","~3 years","Zooplankton, parasites","Least Concern","A classic model of sex change: the largest female becomes a blue-headed terminal male.","Coral reefs and seagrass.","Picks plankton and cleans other fish.","Protogynous sex change; two male types (terminal and initial phase).","Resident.","Daily spawning at reef edges."),
("sweetlips-oriental","Oriental sweetlips","Plectorhinchus vittatus",2,25,["Indo-Pacific"],"Up to 86 cm","Unknown","Crustaceans, molluscs","Least Concern","Juveniles are spotted and wriggle like flatworms; adults are striped.","Coral reefs.","Nocturnal feeder on invertebrates.","Pelagic spawning.","Resident.","Rests in groups under ledges by day."),
("cardinalfish-banggai","Banggai cardinalfish","Pterapogon kauderni",0,6,["Banggai Islands, Indonesia"],"~8 cm","Unknown","Zooplankton","Endangered","A rare reef fish whose males brood eggs and young in their mouths.","Seagrass and shallow reefs among sea urchins.","Feeds on plankton.","Male mouth-brooding; no pelagic larval stage.","Very low dispersal.","Shelters among urchin spines."),
("damselfish-garibaldi","Garibaldi","Hypsypops rubicundus",0,30,["Eastern Pacific, California"],"~30 cm","~15 years","Sponges, invertebrates","Least Concern","California's bright orange state marine fish.","Rocky kelp reefs.","Picks sponges and small invertebrates.","Males cultivate red-algae nests; females choose nests that already hold eggs.","Resident.","Highly territorial; makes thumping sounds."),
("soldierfish","Blackbar soldierfish","Myripristis jacobus",1,100,["Atlantic"],"~25 cm","Unknown","Zooplankton","Least Concern","A big-eyed, red nocturnal fish that hides in caves by day.","Reef caves and ledges.","Leaves at night to eat plankton.","Pelagic eggs.","Resident.","Grunting sounds; red is camouflaged in the dark."),
("barracuda-great","Great barracuda","Sphyraena barracuda",0,100,["Tropical worldwide"],"Up to 1.9 m","~14 years","Fish","Least Concern","A lightning-fast predator with fang-like teeth.","Reefs, seagrass, open water.","Short, explosive bursts; may herd prey.","Spawns offshore.","Juveniles in mangroves; adults roam.","Curious; follows divers."),
("lined-surgeonfish","Lined surgeonfish","Acanthurus lineatus",0,6,["Indo-Pacific"],"~38 cm","~45 years","Algae","Least Concern","A boldly striped grazer that fiercely defends algae 'lawns' in the surf zone.","Shallow wave-washed reef flats.","Farms and grazes filamentous algae.","Pelagic spawning.","Resident.","Territorial; tail spine is venomous."),
])
